use App\Http\Controllers\Controller;use App\Models\ScreenshotStorageJob;use App\Models\ScreenshotStorageProvider;use App\Services\Billing\EntitlementService;use App\Services\ScreenshotStorage\ScreenshotStorageService;use App\Services\ScreenshotStorage\StorageProviderFactory;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Validator;use Illuminate\Support\Str;use Illuminate\Validation\Rule;
/** Provides screenshot storage controller behavior within the WorkIntel application. */ class ScreenshotStorageController extends Controller
{
    /** Returns the requested resource collection. */ public function index(Request $request,ScreenshotStorageService $storage):JsonResponse{$workspace=$request->attributes->get('workspace');$storage->ensureLocalProvider($workspace);$providers=ScreenshotStorageProvider::where('workspace_id',$workspace->id)->orderByDesc('is_primary')->orderBy('name')->get()->map(fn($p)=>$this->payload($p));$jobs=ScreenshotStorageJob::where('workspace_id',$workspace->id)->selectRaw('status, COUNT(*) as total')->groupBy('status')->pluck('total','status');return response()->json(['providers'=>$providers,'provider_types'=>$this->providerTypes(),'jobs'=>$jobs,'external_storage_entitled'=>app(EntitlementService::class)->allowed($workspace,'feature.external_screenshot_storage')]);}
    /** Creates and persists the requested resource. */ public function store(Request $request):JsonResponse{$workspace=$request->attributes->get('workspace');app(EntitlementService::class)->assertFeature($workspace,'feature.external_screenshot_storage');$data=$request->validate(['name'=>'required|string|max:120','provider_type'=>['required',Rule::in(StorageProviderFactory::TYPES)],'root_path'=>'nullable|string|max:500','fallback_to_local'=>'boolean','delete_local_after_sync'=>'boolean','config'=>'nullable|array']);abort_if($data['provider_type']==='local',422,'The system local provider is created automatically.');$config=$this->validateConfig($data['provider_type'],$data['config']??[],false);$provider=ScreenshotStorageProvider::create(['uuid'=>(string)Str::uuid(),'workspace_id'=>$workspace->id,'name'=>$data['name'],'provider_type'=>$data['provider_type'],'enabled'=>true,'is_primary'=>false,'fallback_to_local'=>$data['fallback_to_local']??true,'delete_local_after_sync'=>$data['delete_local_after_sync']??false,'root_path'=>$data['root_path']??null,'encrypted_config'=>$config,'created_by'=>$request->user()->id,'updated_by'=>$request->user()->id]);return response()->json(['message'=>'Storage provider created.','provider'=>$this->payload($provider)],201);}
