    /** Handles the activate operation for the current WorkIntel workflow. */ public function activate(Request $request,ScreenshotStorageProvider $provider):JsonResponse{$workspace=$request->attributes->get('workspace');$this->assertWorkspace($provider,$workspace->id);if($provider->provider_type!=='local')app(EntitlementService::class)->assertFeature($workspace,'feature.external_screenshot_storage');abort_unless($provider->enabled,422,'Enable the provider first.');if($provider->provider_type!=='local')abort_unless($provider->health_status==='healthy',422,'Test and verify the storage connection before making it primary.');DB::transaction(function()use($provider,$workspace){ScreenshotStorageProvider::where('workspace_id',$workspace->id)->update(['is_primary'=>false]);$provider->update(['is_primary'=>true]);});return response()->json(['message'=>$provider->name.' is now the primary screenshot storage provider.','provider'=>$this->payload($provider->fresh())]);}
