    /** Handles the queue existing operation for the current WorkIntel workflow. */ public function queueExisting(Request $request,ScreenshotStorageProvider $provider,ScreenshotStorageService $storage):JsonResponse{$workspace=$request->attributes->get('workspace');$this->assertWorkspace($provider,$workspace->id);abort_if($provider->provider_type==='local',422,'Existing screenshots are already on local storage.');app(EntitlementService::class)->assertFeature($workspace,'feature.external_screenshot_storage');$data=$request->validate(['limit'=>'nullable|integer|min:1|max:5000']);$count=$storage->queueExisting($workspace,$provider,(int)($data['limit']??500));return response()->json(['message'=>"Queued {$count} screenshot(s) for storage migration.",'queued'=>$count]);}
