    /** Handles the assert workspace operation for the current WorkIntel workflow. */ private function assertWorkspace(ScreenshotStorageProvider $provider,int $workspaceId):void{abort_unless((int)$provider->workspace_id===$workspaceId,404);}
    /** Handles the provider types operation for the current WorkIntel workflow. */ private function providerTypes():array{return[['key'=>'local','label'=>'Server Local'],['key'=>'ftp','label'=>'FTP'],['key'=>'sftp','label'=>'SFTP'],['key'=>'s3','label'=>'AWS S3 / S3 Compatible'],['key'=>'google_drive','label'=>'Google Drive'],['key'=>'onedrive','label'=>'Microsoft OneDrive'],['key'=>'azure_blob','label'=>'Azure Blob Storage']];}
    /** Validates validate config input before it is processed. */ private function validateConfig(string $type,array $config,bool $existing):array{$rules=match($type){'ftp'=>['host'=>'required|string|max:255','port'=>'nullable|integer|min:1|max:65535','username'=>'required|string|max:255','password'=>[$existing?'nullable':'required','string','max:2000'],'passive'=>'nullable|boolean','ssl'=>'nullable|boolean'],'sftp'=>['host'=>'required|string|max:255','port'=>'nullable|integer|min:1|max:65535','username'=>'required|string|max:255','password'=>'nullable|string|max:2000','private_key_path'=>'nullable|string|max:1000','public_key_path'=>'nullable|string|max:1000','passphrase'=>'nullable|string|max:2000'],'s3'=>['access_key'=>'required|string|max:500','secret_key'=>[$existing?'nullable':'required','string','max:2000'],'region'=>'required|string|max:100','bucket'=>'required|string|max:255','endpoint'=>'nullable|url|max:1000','session_token'=>'nullable|string|max:4000'],'google_drive'=>['access_token'=>'nullable|string|max:8000','refresh_token'=>'nullable|string|max:8000','client_id'=>'nullable|string|max:1000','client_secret'=>'nullable|string|max:2000','folder_id'=>'nullable|string|max:500'],'onedrive'=>['access_token'=>'nullable|string|max:8000','refresh_token'=>'nullable|string|max:8000','client_id'=>'nullable|string|max:1000','client_secret'=>'nullable|string|max:2000','tenant_id'=>'nullable|string|max:500','drive_id'=>'nullable|string|max:500'],'azure_blob'=>['account_url'=>'required|url|max:1000','container'=>'required|string|max:255','sas_token'=>[$existing?'nullable':'required','string','max:8000']],default=>[]};$v=Validator::make($config,$rules);$v->after(function($v)use($type,$config){if(in_array($type,['google_drive','onedrive'],true)){if(empty($config['access_token'])&&(empty($config['refresh_token'])||empty($config['client_id'])||empty($config['client_secret'])))$v->errors()->add('config','Provide an access token or OAuth refresh credentials.');}if($type==='sftp'&&empty($config['password'])&&empty($config['private_key_path']))$v->errors()->add('config','SFTP requires a password or private key path.');if($type==='s3'&&!empty($config['endpoint'])){$parts=parse_url((string)$config['endpoint']);if(!empty($parts['user'])||!empty($parts['pass']))$v->errors()->add('config.endpoint','Do not place credentials in the S3 endpoint URL.');}if($type==='azure_blob'&&!empty($config['account_url'])){$parts=parse_url((string)$config['account_url']);if(!empty($parts['user'])||!empty($parts['pass'])||!empty($parts['query']))$v->errors()->add('config.account_url','Azure account URL must not contain credentials or query parameters.');}});return$v->validate();}
    /** Handles the payload operation for the current WorkIntel workflow. */ private function payload(ScreenshotStorageProvider $p):array{$config=$p->encrypted_config??[];$public=[];$sensitive=['password','secret_key','session_token','access_token','refresh_token','client_secret','sas_token','passphrase'];foreach($config as $k=>$v)if(!in_array($k,$sensitive,true))$public[$k]=$v;return['id'=>$p->id,'uuid'=>$p->uuid,'name'=>$p->name,'provider_type'=>$p->provider_type,'enabled'=>$p->enabled,'is_primary'=>$p->is_primary,'fallback_to_local'=>$p->fallback_to_local,'delete_local_after_sync'=>$p->delete_local_after_sync,'root_path'=>$p->root_path,'health_status'=>$p->health_status,'consecutive_failures'=>$p->consecutive_failures,'last_tested_at'=>$p->last_tested_at?->toIso8601String(),'last_success_at'=>$p->last_success_at?->toIso8601String(),'last_failure_at'=>$p->last_failure_at?->toIso8601String(),'last_error'=>$p->last_error,'public_config'=>$public,'configured_secret_fields'=>array_values(array_filter($sensitive,fn($k)=>!empty($config[$k]??null)))];}
